import React from "react";
import './HeaderComponent.scss';
import 'bootstrap-icons/font/bootstrap-icons.css';
import 'font-awesome/css/font-awesome.min.css';

const Header = () => {
    return (
        <div className="navbar">
            <div className="navbar-left">
                <span className="brand">Admin</span>
                <div className="nav-links">
                    <ul className="nav nav-icons">
                        <li><i className="bi bi-folder"></i></li>
                        <li><i className="bi bi-eye"></i></li>
                        <li><i className="bi bi-bar-chart"></i></li>
                    </ul>
                    <form className="navbar-search" action="#">
                        <input type="text" className="search-input" placeholder="Search..." />
                        <button className="btn" type="button">
                            <i className="bi bi-search"></i>
                        </button>
                    </form>
                </div>
            </div>

            <div className="navbar-right">
                <span className="user-name">Barbara Saunders</span>
                <a href="#" className="icon-link"><i className="fas fa-envelope"></i></a>
                <div className="user-avatar">
                    <i className="fas fa-user"></i>
                </div>
            </div>
        </div>

    );
};

export default Header;
